theorem CategoryGame.residual_has_dense_open_sequence.{u} {X : Type u} [TopologicalSpace X] {S : Set X}
  (hS : Membership.mem (residual X) S) :
  Exists fun D => And (∀ (n : Nat), IsOpen (D n)) (And (∀ (n : Nat), Dense (D n)) (LE.le (Set.iInter fun n => D n) S))

theorem CategoryGame.first_winning_of_open_residual.{u} {X : Type u} [MetricSpace X] [CompleteSpace X] {A : Set X}
  (U : CategoryGame.OpenMove X) {S : Set X} (hS : Membership.mem (residual X) S)
  (hSA : LE.le (Inter.inter (Subtype.val U) S) A) : Exists fun σ => CategoryGame.FirstWins X A σ
